CREATE TABLE app_user(id BIGSERIAL PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(16) NOT NULL CHECK(role IN ('USER','ADMIN')));
CREATE TABLE refresh_token(id VARCHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_user(id), expires_at TIMESTAMPTZ NOT NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE airport(code VARCHAR(3) PRIMARY KEY, city VARCHAR(80) NOT NULL, name VARCHAR(160) NOT NULL);
CREATE TABLE airline(id BIGINT PRIMARY KEY, name VARCHAR(80) NOT NULL, code VARCHAR(4) NOT NULL);
CREATE TABLE aircraft(id BIGSERIAL PRIMARY KEY, type VARCHAR(80) NOT NULL, layout VARCHAR(16) NOT NULL, rows INTEGER NOT NULL, columns_count INTEGER NOT NULL);
CREATE TABLE fare_class(code VARCHAR(16) PRIMARY KEY, multiplier NUMERIC(10,2) NOT NULL, baggage VARCHAR(160) NOT NULL);
CREATE TABLE extra(code VARCHAR(32) PRIMARY KEY, name VARCHAR(80) NOT NULL, kind VARCHAR(16) NOT NULL, price NUMERIC(12,2) NOT NULL);
CREATE TABLE flight(id BIGSERIAL PRIMARY KEY, aircraft_id BIGINT NOT NULL REFERENCES aircraft(id), airline_id BIGINT NOT NULL REFERENCES airline(id), flight_number VARCHAR(12) NOT NULL, origin VARCHAR(3) NOT NULL REFERENCES airport(code), destination VARCHAR(3) NOT NULL REFERENCES airport(code), departure TIMESTAMPTZ NOT NULL, arrival TIMESTAMPTZ NOT NULL, base_price NUMERIC(12,2) NOT NULL, status VARCHAR(16) NOT NULL, version BIGINT NOT NULL DEFAULT 0, CHECK(origin <> destination), CHECK(arrival > departure));
CREATE INDEX flight_search_idx ON flight(origin,destination,departure);
CREATE TABLE booking(id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_user(id), flight_id BIGINT NOT NULL REFERENCES flight(id), pnr VARCHAR(8) NOT NULL UNIQUE, status VARCHAR(16) NOT NULL, total NUMERIC(12,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL, request_id VARCHAR(80) NOT NULL UNIQUE);
CREATE INDEX booking_user_idx ON booking(user_id,created_at DESC);
CREATE TABLE flight_seat(id BIGSERIAL PRIMARY KEY, flight_id BIGINT NOT NULL REFERENCES flight(id), seat_number VARCHAR(4) NOT NULL, row_number INTEGER NOT NULL, column_index INTEGER NOT NULL, cabin VARCHAR(16) NOT NULL REFERENCES fare_class(code), features VARCHAR(255) NOT NULL, surcharge NUMERIC(12,2) NOT NULL, blocked BOOLEAN NOT NULL DEFAULT false, hold_id VARCHAR(36), hold_user_id BIGINT REFERENCES app_user(id), hold_expires_at TIMESTAMPTZ, booking_id BIGINT REFERENCES booking(id), version BIGINT NOT NULL DEFAULT 0, UNIQUE(flight_id,seat_number), CHECK(booking_id IS NULL OR hold_id IS NULL));
CREATE INDEX seat_expiry_idx ON flight_seat(hold_expires_at) WHERE hold_id IS NOT NULL;
CREATE INDEX seat_hold_idx ON flight_seat(hold_id);
CREATE TABLE seat_hold(id VARCHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_user(id), flight_id BIGINT NOT NULL REFERENCES flight(id), seat_id BIGINT NOT NULL REFERENCES flight_seat(id), expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE passenger(id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES booking(id), name VARCHAR(80) NOT NULL, date_of_birth DATE NOT NULL, seat_number VARCHAR(4) NOT NULL, baggage VARCHAR(32) NOT NULL REFERENCES extra(code), meal VARCHAR(32) NOT NULL REFERENCES extra(code));
CREATE TABLE booking_seat(id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES booking(id), flight_id BIGINT NOT NULL REFERENCES flight(id), seat_number VARCHAR(4) NOT NULL, active BOOLEAN NOT NULL, FOREIGN KEY(flight_id,seat_number) REFERENCES flight_seat(flight_id,seat_number));
CREATE UNIQUE INDEX confirmed_seat_unique ON booking_seat(flight_id,seat_number) WHERE active;
CREATE TABLE payment(id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL UNIQUE REFERENCES booking(id), amount NUMERIC(12,2) NOT NULL, status VARCHAR(32) NOT NULL, reference VARCHAR(40) NOT NULL);
